#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1,2,...,n into positions 0,1,...,n-1
    for(int t = 0; t < n-2; t++){
        // Find where value (t+1) is
        int pos = -1;
        for(int i = t; i < n; i++) if(p[i] == t+1){ pos = i; break; }
        if(pos == t) continue; // already placed

        // Step 1: Move element from pos to position (n-1) if not already there
        if(pos != n-1){
            // We want to make p[pos] go to position n-1
            // Use x = pos+1, y = n-1-pos
            // But need x+y < n: (pos+1)+(n-1-pos) = n, not < n
            // So use x = pos, y = n-1-pos (if pos > 0)
            // After: [suffix of len n-1-pos] [middle of len 1: p[pos]] [prefix of len pos]
            // Element at p[pos] goes to position (n-1-pos) which is after suffix... 
            // Actually: new array = p[n-(n-1-pos)..n-1] + p[pos..pos] + p[0..pos-1]
            //                     = p[pos+1..n-1] + p[pos..pos] + p[0..pos-1]
            // Element p[pos] is at new position (n-1-pos-1) + 1 = n-1-pos... no
            // Suffix has n-1-pos elements (indices pos+1..n-1), then middle is p[pos] at new index n-1-pos, then prefix p[0..pos-1] of length pos
            // So element is at index n-1-pos. We want it at n-1.
            // That means we need pos=0... Let's try differently.

            // Use x=1, y=n-1-pos. Need 1+n-1-pos < n => pos > 0.
            // New: p[pos+1..n-1] + p[1..pos] + p[0]
            // p[0] goes to position n-1. But we want p[pos] at n-1.
            // Instead: use x=pos+1, y=1. Need pos+1+1<n => pos<n-2.
            if(pos < n-2){
                // new = p[n-1] + p[pos+1..n-2] + p[0..pos]
                // p[pos] goes to position 1+(n-2-pos-1+1)+pos = n-1. Wait: prefix len=pos+1, suffix len=1, middle=p[pos+1..n-2]
                // new = [p[n-1]] ++ [p[pos+1..n-2]] ++ [p[0..pos]]
                // p[pos] is at new index 1+(n-2-pos)+pos = n-1. 
                ops.push_back({pos+1, 1});
                apply(p, pos+1, 1);
            } else {
                // pos == n-2. x=1,y=1 => new = p[n-1]+p[1..n-2]+p[0]. Element at n-2 stays at n-2... not helpful
                // x=n-2, y=1: new = p[n-1]+p[n-2..n-2]+p[0..n-3]. Element at n-2 -> pos 1. Then need another op.
                ops.push_back({1, 1});
                apply(p, 1, 1);
                // Recalculate pos
                for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
                if(pos!=n-1 && pos<n-2){
                    ops.push_back({pos+1,1});
                    apply(p,pos+1,1);
                }
            }
            for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
        }
        if(pos==t) continue;
        // Now element should be at n-1. Place it at position t.
        // x=t, y=1 (if t>0): new = p[n-1] + p[t..n-2] + p[0..t-1]. Element at pos 0, want pos t.
        // x=1, y=n-1-t: new = p[t+1..n-1] + p[1..t] + p[0]. Element at n-1 -> within suffix at index n-1-t-1=n-2-t... no
        // Actually if element is at n-1: use x=t, y=1 => elem goes to pos 0. Not t.
        // Use x=n-1-t, y=1: need n-1-t+1<n => t>0. new=p[n-1]+p[n-1-t..n-2]+p[0..n-2-t]. Elem at pos 0.
        // Hmm. Let me just use: x=t+1, y=n-1-t, need t+1+n-1-t<n => n<n, false. 
        // x=t, y=n-t-1 if t>0: x+y=n-1<n. new=p[t+1..n-1]+p[t..t]+p[0..t-1]. elem at n-1 -> in suffix at relative pos n-1-(t+1)=n-t-2. Actual pos=n-t-2. Not t.
        if(pos==n-1 && t==0){
            ops.push_back({1,n-2});
            apply(p,1,n-2);
        } else if(pos==n-1){
            ops.push_back({t, n-1-t});
            apply(p, t, n-1-t);
            // elem was at n-1, now in suffix starting at pos 0, it's at pos n-1-t-1... let me just recheck
            for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
            if(pos!=t){
                // try one more
                if(pos<n-2){ops.push_back({pos+1,1});apply(p,pos+1,1);}
                for(int i=t;i<n;i++) if(p[i]==t+1){pos=i;break;}
                if(pos!=t && pos==n-1 && t<n-2){ops.push_back({t+1,n-1-t-1});apply(p,t+1,n-1-t-1);}
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
